// --- Vue 3 (<script setup>：响应式 props/ref + computed 派生 + v-model) ---
const props = defineProps({ courses: { type: Array, required: true } })
const query = ref('')
const visibleCourses = computed(() =>
  props.courses.filter(c => c.name.includes(query.value))
)
// 模板：<input v-model="query">
//       <ul><li v-for="c in visibleCourses" :key="c.id">{{ c.name }}</li></ul>

// --- React (状态快照风格：Render 期直接计算派生值 + 受控输入框) ---
function CourseList({ courses }) {
  const [query, setQuery] = useState('')
  // 派生列表直接由本轮快照算出，不另存为独立 useState
  const visibleCourses = courses.filter(c => c.name.includes(query))
  return (
    <>
      <input
        value={query}
        onChange={e => setQuery(e.target.value)}
      />
      <ul>
        {visibleCourses.map(c => <li key={c.id}>{c.name}</li>)}
      </ul>
    </>
  )
}
